import { getStorage, postMediaFolder } from './storage/index.js';

/**
 * The Feed's only door to file storage. Feed code never touches a driver, a
 * path or a provider: it saves bytes into a post's slot and gets back a URL and
 * a storage key. Swapping the storage driver changes nothing here.
 *
 * Keys are generated by the driver (content hash inside a server-built folder),
 * never taken from the client.
 */

/** Stores one file for [postId]'s [slot] (`media-0`, `media-0-thumbnail`). */
export const savePostMedia = async (buffer, { postId, slot, extension }) => {
  const storage = getStorage();
  const url = await storage.save(buffer, { folder: postMediaFolder(String(postId), slot), extension });
  return { url, storageKey: storage.keyFor(url) };
};

/** Deletes a stored file by key. Missing files are not an error. */
export const removePostMedia = async (storageKey) => {
  if (!storageKey) return false;
  const storage = getStorage();
  return storage.remove(storage.urlFor(storageKey));
};

export const postMediaExists = (storageKey) => (storageKey ? getStorage().exists(storageKey) : Promise.resolve(false));

export default { savePostMedia, removePostMedia, postMediaExists };
